export default {
  title: 'Oh My Posh',
  tagline: 'The most customizable and fastest prompt engine for any shell.',
  url: 'https://ohmyposh.dev',
  baseUrl: '/',
  favicon: 'img/favicons.svg',
  organizationName: 'jandedobbeleer',
  projectName: 'oh-my-posh',
  onBrokenLinks: 'throw',
  plugins: [
    './plugins/appinsights'
  ],
  headTags: [
    {
      tagName: 'link',
      attributes: {
        rel: 'alternate',
        type: 'text/plain',
        title: 'llms.txt',
        href: '/llms.txt',
      },
    },
  ],
  stylesheets: [
    "https://rsms.me/inter/inter.css"
  ],
  themeConfig: {
    metadata: [
      {property: 'og:image', content: 'https://ohmyposh.dev/img/hero.png'},
      {property: 'og:type', content: 'website'},
    ],
    colorMode: {
      defaultMode: 'light',
      disableSwitch: false,
      respectPrefersColorScheme: true,
    },
    prism: {
      additionalLanguages: ['powershell', 'lua', 'jsstacktrace', 'toml'],
    },
    docs: {
        sidebar: {
          hideable: true,
        },
    },
    navbar: {
      title: 'Oh My Posh',
      logo: {
        alt: 'Oh My Posh Logo',
        src: 'img/logo-dark.svg',
        srcDark: 'img/logo-light.svg',
      },
      items: [
        {
          to: 'docs',
          activeBasePath: 'docs',
          label: 'Docs',
          position: 'left',
        },
        {
          to: 'docs/segments/overview',
          label: 'Segments',
          position: 'left',
        },
        {
          to: 'docs/themes',
          label: 'Themes',
          position: 'left',
        },
        {
          to: 'blog',
          label: 'Blog',
          position: 'left'
        },
        {
          href: 'https://github.com/jandedobbeleer/oh-my-posh',
          className: 'header-github-link',
          'aria-label': 'GitHub repository',
          position: 'right',
        },
        {
          href: 'https://discord.gg/n7E3DkXssv',
          className: 'header-discord-link',
          'aria-label': 'Discord',
          position: 'right',
        },
        {
          href: 'https://staging.bsky.app/profile/ohmyposh.dev',
          className: 'header-bluesky-link',
          'aria-label': 'Bluesky',
          position: 'right',
        }
      ],
    },
    footer: {
      style: 'dark',
      links: [
        {
          title: 'How to',
          items: [
            {
              label: 'Getting started',
              to: 'docs/',
            },
            {
              label: 'Contributing',
              to: 'docs/contributing/started',
            },
          ],
        },
        {
          title: 'Social',
          items: [
            {
              label: 'GitHub',
              href: 'https://github.com/jandedobbeleer/oh-my-posh',
            },
            {
              label: 'Discord',
              href: 'https://discord.gg/n7E3DkXssv',
            },
            {
              label: 'Bluesky',
              href: 'https://staging.bsky.app/profile/ohmyposh.dev',
            }
          ],
        },
        {
          title: 'Links',
          items: [
            {
              label: 'Docusaurus',
              href: 'https://github.com/facebook/docusaurus',
            },
            {
              label: 'Privacy',
              href: '/privacy',
            },
          ],
        },
        {
          title: 'Support',
          items: [
            {
              label: 'GitHub Sponsors',
              href: 'https://github.com/sponsors/JanDeDobbeleer',
            },
            {
              label: 'Product spotlight',
              href: 'https://buy.polar.sh/REDACTED',
            },
            {
              label: 'Swag',
              href: 'https://swag.ohmyposh.dev',
            },
          ],
        },
        {
          title: 'Our sponsors',
          items: [
            {
              label: 'CodeRabbit',
              href: 'https://coderabbit.link/posh',
            },
          ],
        },
      ],
      copyright: `Copyright © ${new Date().getFullYear()} <a href='https://github.com/sponsors/JanDeDobbeleer' target='_blank'>Jan De Dobbeleer</a> and <a href='/docs/contributors'>contributors</a>.`,
    },
    appInsights: {
      instrumentationKey: 'REDACTED',
    },
    algolia: {
      appId: 'XIR4RB3TM1',
      apiKey: 'REDACTED',
      indexName: 'ohmyposh',
    },
  },
  presets: [
    [
      '@docusaurus/preset-classic',
      {
        docs: {
          sidebarPath: './sidebars.js',
          editUrl: 'https://github.com/jandedobbeleer/oh-my-posh/edit/main/website/',
        },
        theme: {
          customCss: [
            './src/css/prism-rose-pine-moon.css',
            './src/css/custom.css'
          ],
        },
        blog: {
          onInlineAuthors: 'ignore'
        },
      },
    ],
  ],
};

import Link from "@docusaurus/Link";
import useBaseUrl from "@docusaurus/useBaseUrl";
import useDocusaurusContext from "@docusaurus/useDocusaurusContext";
import Layout from "@theme/Layout";
import Head from "@docusaurus/Head";
import Tabs from "@theme/Tabs";
import TabItem from "@theme/TabItem";
import CodeBlock from "@theme/CodeBlock";
import classnames from "classnames";
import styles from "./styles.module.css";

const features = [
  {
    title: <>One config, every shell</>,
    description: (
      <>
        Write your prompt once and run it everywhere: PowerShell, Bash, Zsh, Fish, Nu, and
        more. Windows, macOS, Linux, WSL, containers, SSH sessions &mdash; no vendor lock-in.
      </>
    ),
  },
  {
    title: <>Fast by construction</>,
    description: (
      <>
        Built in Go with smart caching and async segment execution. Your prompt renders
        instantly, even with complex configurations and multiple segments running.
      </>
    ),
  },
  {
    title: <>117 segments</>,
    description: (
      <>
        Git status, cloud context, language versions, system metrics and more, composed
        with a template language so your prompt adapts to what you're working on.
      </>
    ),
  },
];

const shells = [
  "bash",
  "cmd",
  "elvish",
  "fish",
  "nu",
  "powershell",
  "xonsh",
  "yash",
  "zsh",
];

function Feature({ title, description }) {
  return (
    <div className={classnames("col col--4", styles.feature)}>
      <h3>{title}</h3>
      <p>{description}</p>
    </div>
  );
}

function Home() {
  const context = useDocusaurusContext();
  const { siteConfig = {} } = context;

  const websiteJsonLd = JSON.stringify({
    "@context": "https://schema.org",
    "@type": "WebSite",
    "url": "https://ohmyposh.dev/",
    "name": "Oh My Posh",
    "description": siteConfig.tagline,
  });

  const organizationJsonLd = JSON.stringify({
    "@context": "https://schema.org",
    "@type": "Organization",
    "name": "Oh My Posh",
    "url": "https://ohmyposh.dev/",
    "logo": "https://ohmyposh.dev/img/logo.png",
    "description": siteConfig.tagline,
    "sameAs": [
      "https://github.com/JanDeDobbeleer/oh-my-posh",
    ],
  });

  return (
    <Layout title="Home" description={`${siteConfig.tagline}`}>
      <Head>
        <script type="application/ld+json" dangerouslySetInnerHTML={{__html: websiteJsonLd}} />
        <script type="application/ld+json" dangerouslySetInnerHTML={{__html: organizationJsonLd}} />
      </Head>
      <header className={styles.heroBanner}>
        <div className="container">
          <h1 className="hero__title">A prompt that knows where you are.</h1>
          <p className={classnames("hero__subtitle", styles.subtitle)}>{siteConfig.tagline}</p>

          <div className={styles.installBox}>
            <Tabs
              groupId="install-os"
              defaultValue="windows"
              values={[
                { label: "Windows", value: "windows" },
                { label: "macOS", value: "macos" },
                { label: "Linux", value: "linux" },
              ]}
            >
              <TabItem value="windows">
                <CodeBlock language="powershell">
                  winget install JanDeDobbeleer.OhMyPosh --source winget
                </CodeBlock>
              </TabItem>
              <TabItem value="macos">
                <CodeBlock language="bash">
                  brew install jandedobbeleer/oh-my-posh/oh-my-posh
                </CodeBlock>
              </TabItem>
              <TabItem value="linux">
                <CodeBlock language="bash">
                  curl -s https://ohmyposh.dev/install.sh | bash -s
                </CodeBlock>
              </TabItem>
            </Tabs>
            <p className={styles.installNote}>
              Other options and package managers in the{" "}
              <Link to={useBaseUrl("docs/installation/windows")}>installation guide</Link>.
            </p>
          </div>

          <div className={styles.buttons}>
            <Link
              className="button button--primary button--lg"
              to={useBaseUrl("docs/")}
            >
              Get started &rarr;
            </Link>
            <Link
              className="button button--outline button--primary button--lg"
              to={useBaseUrl("docs/themes")}
            >
              Browse themes &rarr;
            </Link>
          </div>

          <img
            className={styles.heroImage}
            src="/img/hero.png"
            width="1100"
            height="44"
            alt="The default Oh My Posh prompt"
          />
        </div>
      </header>
      <main>
        {features && features.length > 0 && (
          <section className={styles.features}>
            <div className="container">
              <div className="row">
                {features.map((props, idx) => (
                  <Feature key={idx} {...props} />
                ))}
              </div>
            </div>
          </section>
        )}
        <section className={styles.shellRow}>
          <div className="container">
            <p className={styles.shellList}>Works with {shells.join(" · ")}</p>
          </div>
        </section>
      </main>
    </Layout>
  );
}

export default Home;

