<title>Oh My Posh — website design & IA proposal</title>

<style>
/* ─────────────────────────────────────────────────────────────
   Document shell tokens
   Neutral ramp carries a slight blue-slate bias, borrowed from
   the product's own rose-pine/terminal ground rather than a
   pure grey.
   ───────────────────────────────────────────────────────────── */
:root {
  --ink:        #131820;
  --ink-2:      #3d4757;
  --ink-3:      #6b7788;
  --ground:     #f7f8fa;
  --panel:      #ffffff;
  --rule:       #dde2ea;
  --rule-soft:  #e9edf3;
  --accent:     #1f6fd0;
  --accent-ink: #0f4c96;
  --accent-wash:#e8f0fb;
  --amber:      #a86b12;
  --amber-wash: #fdf3e0;
  --good:       #1a7f52;
  --bad:        #b4453a;

  --mono: ui-monospace, "SF Mono", "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Menlo, Consolas, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;

  --measure: 68ch;
  --pad: clamp(1.25rem, 4vw, 3rem);
}

@media (prefers-color-scheme: dark) {
  :root {
    --ink:        #e3e9f2;
    --ink-2:      #a5b1c2;
    --ink-3:      #7b8798;
    --ground:     #0e1117;
    --panel:      #151a22;
    --rule:       #262e3a;
    --rule-soft:  #1d242e;
    --accent:     #63a4f0;
    --accent-ink: #a8caf7;
    --accent-wash:#15243a;
    --amber:      #e0ac5a;
    --amber-wash: #2a2115;
    --good:       #4fbf8b;
    --bad:        #e07a6e;
  }
}

:root[data-theme="dark"] {
  --ink:        #e3e9f2;
  --ink-2:      #a5b1c2;
  --ink-3:      #7b8798;
  --ground:     #0e1117;
  --panel:      #151a22;
  --rule:       #262e3a;
  --rule-soft:  #1d242e;
  --accent:     #63a4f0;
  --accent-ink: #a8caf7;
  --accent-wash:#15243a;
  --amber:      #e0ac5a;
  --amber-wash: #2a2115;
  --good:       #4fbf8b;
  --bad:        #e07a6e;
}

:root[data-theme="light"] {
  --ink:        #131820;
  --ink-2:      #3d4757;
  --ink-3:      #6b7788;
  --ground:     #f7f8fa;
  --panel:      #ffffff;
  --rule:       #dde2ea;
  --rule-soft:  #e9edf3;
  --accent:     #1f6fd0;
  --accent-ink: #0f4c96;
  --accent-wash:#e8f0fb;
  --amber:      #a86b12;
  --amber-wash: #fdf3e0;
  --good:       #1a7f52;
  --bad:        #b4453a;
}

/* ── base ───────────────────────────────────────────────────── */
.doc {
  background: var(--ground);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
.doc *,
.doc *::before,
.doc *::after { box-sizing: border-box; }

.wrap {
  max-width: 1120px;
  margin: 0 auto;
  padding: 0 var(--pad);
}

.doc h1, .doc h2, .doc h3, .doc h4 {
  text-wrap: balance;
  letter-spacing: -0.018em;
  line-height: 1.15;
  margin: 0;
  font-weight: 640;
}

.doc p { margin: 0; max-width: var(--measure); }
.doc a { color: var(--accent); text-decoration-thickness: 1px; text-underline-offset: 2px; }
.doc a:focus-visible,
.doc button:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 3px; }

/* Eyebrow — monospace is the subject's own vernacular, used only
   as a structural marker, never as body text. */
.eyebrow {
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-3);
  margin: 0;
}

.stack   { display: flex; flex-direction: column; }
.gap-2   { gap: 0.5rem; }
.gap-3   { gap: 0.75rem; }
.gap-4   { gap: 1rem; }
.gap-6   { gap: 1.5rem; }
.gap-8   { gap: 2rem; }

section.band { padding: clamp(2.75rem, 6vw, 4.5rem) 0; border-top: 1px solid var(--rule-soft); }
section.band:first-of-type { border-top: 0; }

.lede { font-size: 1.075rem; color: var(--ink-2); }
.small { font-size: 0.875rem; color: var(--ink-2); }
.tiny { font-size: 0.8rem; color: var(--ink-3); }

/* ── masthead ───────────────────────────────────────────────── */
.masthead {
  padding: clamp(3rem, 8vw, 5.5rem) 0 clamp(2rem, 4vw, 3rem);
  border-bottom: 1px solid var(--rule);
}
.masthead h1 {
  font-size: clamp(2rem, 5.2vw, 3.1rem);
  max-width: 20ch;
}
.masthead .lede { max-width: 60ch; font-size: 1.15rem; }

.meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.75rem;
  font-family: var(--mono);
  font-size: 0.75rem;
  color: var(--ink-3);
  border-top: 1px solid var(--rule-soft);
  padding-top: 1rem;
}
.meta-row b { color: var(--ink-2); font-weight: 500; }

/* ── findings ───────────────────────────────────────────────── */
.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 1px;
  background: var(--rule);
  border: 1px solid var(--rule);
  border-radius: 8px;
  overflow: hidden;
}
.stat {
  background: var(--panel);
  padding: 1.1rem 1.15rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}
.stat .n {
  font-family: var(--mono);
  font-size: 1.6rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em;
  color: var(--ink);
}
.stat .n.warn { color: var(--bad); }
.stat .l { font-size: 0.8rem; color: var(--ink-3); line-height: 1.35; }

