cd /d/oh-my-posh && node -e '
const fs=require("fs"),path=require("path");
const go=fs.readFileSync("src/config/segment_types.go","utf8");
const start=go.indexOf("var Segments = map[SegmentType]func() SegmentWriter{");
const body=go.slice(start,go.indexOf("\n}",start));
const mapKeys=[...body.matchAll(/^\t([A-Z0-9_]+):/gm)].map(m=>m[1]);
const consts=Object.fromEntries([...go.matchAll(/^\t([A-Z0-9_]+)\s+SegmentType = "([a-z0-9_-]+)"/gm)].map(m=>[m[1],m[2]]));
const types=mapKeys.map(k=>consts[k]).filter(Boolean);
const docs=[];
for(const g of fs.readdirSync("website/docs/segments",{withFileTypes:true}))
  if(g.isDirectory()) for(const f of fs.readdirSync("website/docs/segments/"+g.name))
    docs.push(f.replace(/\.mdx$/,""));
console.log("map entries:",mapKeys.length,"| const decls:",Object.keys(consts).length,"| types resolved:",types.length,"| doc files:",docs.length);
const dupes=mapKeys.filter((k,i)=>mapKeys.indexOf(k)!==i);
console.log("dupe map keys:",dupes);
console.log("map keys with no const:",mapKeys.filter(k=>!consts[k]));
const dset=new Set(docs), tset=new Set(types);
console.log("\ntypes with NO doc file:",types.filter(t=>!dset.has(t)).sort().join(" "));
console.log("\ndoc files with NO type:",docs.filter(d=>!tset.has(d)).sort().join(" "));
'

