import React from 'react';
import Link from '@docusaurus/Link';
import useBaseUrl from '@docusaurus/useBaseUrl';
import { usePluginData } from '@docusaurus/useGlobalData';
import Layout from '@theme/Layout';
import SegmentCatalog from '@site/src/components/SegmentCatalog';

function Segments() {
  const data = usePluginData('oh-my-posh-segments');
  // `data` is undefined only when the segments plugin isn't registered in
  // docusaurus.config.js yet - never hardcode the count here, fall back to a
  // count-free sentence instead.
  const description = data
    ? `Browse all ${data.total} Oh My Posh segments — filter by category and setup requirements.`
    : 'Browse Oh My Posh segments — filter by category and setup requirements.';

  return (
    <Layout title="Segments" description={description}>
      <div className="container margin-vert--lg">
        <h1>Segments</h1>
        <p>
          Every segment Oh My Posh ships, filterable by category and setup requirements. See{' '}
          <Link to={useBaseUrl('docs/configuration/segment')}>Segment</Link> for how to add one
          to your prompt.
        </p>
        <SegmentCatalog />
      </div>
    </Layout>
  );
}

export default Segments;

