function SegmentCatalog() {
  const data = usePluginData('oh-my-posh-segments');
  const [filters, setFilters] = useFilters();

  const authLabelById = useMemo(() => {
    if (!data) {
      return {};
    }

    return Object.fromEntries(data.authTiers.map((tier) => [tier.id, tier.label]));
  }, [data]);

  const filtered = useMemo(() => {
    if (!data) {
      return [];
    }

    return data.segments.filter((s) => matchesAll(s, filters));
  }, [data, filters]);

  if (!data) {
    // The registry plugin has not been registered in docusaurus.config.js
    // yet (or loadContent hasn't run). Render a harmless placeholder rather
    // than crashing the build - see the note in the task brief.
    return <p>Segment data is not available.</p>;
  }

