import json, re, sys, glob, os

USERNAME = "jande"
HOSTNAME = "surface-pro"
SANITIZED_EMAIL = "alice@contoso.com"

email_re = re.compile(r'^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$')
win_path_re = re.compile(r'^[A-Za-z]:[\\/]')
unc_path_re = re.compile(r'^\\\\')
unix_path_re = re.compile(r'^/(home|Users|root)(/|$)')
username_re = re.compile(r'(?i)\b' + re.escape(USERNAME) + r'\b')
hostname_re = re.compile(r'(?i)\b' + re.escape(HOSTNAME) + r'\b')

def walk(node, path, hits):
    if isinstance(node, str):
        if not node:
            return
        if email_re.match(node) and node != SANITIZED_EMAIL:
            hits.append(("email", path, node))
        if win_path_re.match(node) or unc_path_re.match(node) or unix_path_re.match(node):
            hits.append(("abspath", path, node))
        if username_re.search(node):
            hits.append(("username", path, node))
        if hostname_re.search(node):
            hits.append(("hostname", path, node))
        return
    if isinstance(node, dict):
        for k, v in node.items():
            walk(v, path + "." + str(k), hits)
        return
    if isinstance(node, list):
        for i, v in enumerate(node):
            walk(v, path + f"[{i}]", hits)

def audit_dir(d):
    total_hits = {}
    for f in sorted(glob.glob(os.path.join(d, "*.data.json"))):
        with open(f, encoding="utf-8") as fh:
            doc = json.load(fh)
        hits = []
        walk(doc, "$", hits)
        if hits:
            total_hits[os.path.basename(f)] = hits
    return total_hits

if __name__ == "__main__":
    d = sys.argv[1]
    hits = audit_dir(d)
    print(f"=== {d}: {len(hits)} files with hits ===")
    for f, h in sorted(hits.items()):
        for kind, path, value in h:
            print(f"{f}: [{kind}] {path} = {value!r}")

