	"github.com/jandedobbeleer/oh-my-posh/src/color"
	"github.com/jandedobbeleer/oh-my-posh/src/shell"
)

// Scratch: exhaustive differential over token triples, asserting VisibleCells
// agrees with the rendered length. Delete after use.
func TestScratchExhaustiveDifferential(t *testing.T) {
	alphabet := []string{
		"a", "ab", "",
		"<LINK>", "<TEXT>", "</TEXT>", "</LINK>",
		"<>", "</>",
		"<transparent,transparent>",
		"<#ff0000,#00ff00>",
		"<b>", "</b>",
		"<transparent,#00ff00>",
		"tail",
	}

	var mismatches int

	var examples []string

	for _, a := range alphabet {
		for _, b := range alphabet {
			for _, c := range alphabet {
				txt := a + b + c

				Init(shell.GENERIC)

				ParentColors = nil
				CurrentColors = &color.Set{Foreground: "#ffffff", Background: "#000000"}
				Colors = &color.Defaults{}

				counted := VisibleCells(txt)

				Write("#000000", "#ffffff", txt)

				_, rendered := String()

				if counted != rendered {
					mismatches++
					if len(examples) < 8 {
						examples = append(examples, txt)
					}
				}
			}
		}
	}

	t.Logf("inputs=%d mismatches=%d", len(alphabet)*len(alphabet)*len(alphabet), mismatches)

	for _, e := range examples {
		t.Logf("  mismatch: %q", e)
	}

	if mismatches != 0 {
		t.Errorf("%d divergences between VisibleCells and rendered length", mismatches)
	}
}

