)

// TestVisibleCellsAgreesWithRenderedLength walks every combination of three
// tokens and asserts the pre-pass and the body writers agree on how many cells
// the text occupies. They are separate scanners over the same grammar, and the
// pre-pass feeds gradient interpolation, the collapse decision and the
// background edge, so a disagreement renders a gradient over the wrong number
// of cells.
//
// Two such disagreements shipped before this existed: a closing link tag read
// as a colour override, and a leading fully transparent anchor the pre-pass
// never saw. Both are single entries in the alphabet below, which is why the
// combinations matter more than any one case.
func TestVisibleCellsAgreesWithRenderedLength(t *testing.T) {
	saveGradientTestGlobals(t)

	alphabet := []string{
		"a", "ab", "", "tail",
		"<LINK>", "<TEXT>", "</TEXT>", "</LINK>",
		"<>", "</>",
		"<transparent,transparent>",
		"<transparent,#00ff00>",
		"<#ff0000,#00ff00>",
		"<b>", "</b>",
	}

	var mismatches []string

	for _, a := range alphabet {
		for _, b := range alphabet {
			for _, c := range alphabet {
				txt := a + b + c

				Init(shell.GENERIC)

				ParentColors = nil
				CurrentColors = &color.Set{Foreground: "#ffffff", Background: "#000000"}
				Colors = &color.Defaults{}

				counted := VisibleCells(txt)

				Write("#000000", "#ffffff", txt)

				_, rendered := String()

				if counted != rendered && len(mismatches) < 10 {
					mismatches = append(mismatches, txt)
				}
			}
		}
	}

	assert.Empty(t, mismatches, "VisibleCells disagreed with the rendered length; first offenders shown")
}

