import struct
import sys


def read_font(path):
    data = open(path, "rb").read()
    num_tables = struct.unpack(">H", data[4:6])[0]
    tables = {}
    for i in range(num_tables):
        off = 12 + i * 16
        tag = data[off:off + 4].decode("latin-1")
        toff, tlen = struct.unpack(">II", data[off + 8:off + 16])
        tables[tag] = (toff, tlen)
    return data, tables


def font_names(data, tables):
    if "name" not in tables:
        return []
    off, _ = tables["name"]
    count, string_off = struct.unpack(">HH", data[off + 2:off + 6])
    names = []
    for i in range(count):
        rec = off + 6 + i * 12
        pid, eid, lid, nid, ln, no = struct.unpack(">HHHHHH", data[rec:rec + 12])
        if nid not in (1, 4, 6):
            continue
        s = data[off + string_off + no:off + string_off + no + ln]
        try:
            text = s.decode("utf-16-be") if pid == 3 else s.decode("latin-1")
        except Exception:
            continue
        names.append((nid, text))
    return names


def cmap_codepoints(data, tables):
    if "cmap" not in tables:
        return set()
    off, _ = tables["cmap"]
    n = struct.unpack(">H", data[off + 2:off + 4])[0]
    best = None
    for i in range(n):
        rec = off + 4 + i * 8
        pid, eid, sub = struct.unpack(">HHI", data[rec:rec + 8])
        if (pid, eid) in ((3, 10), (3, 1), (0, 4), (0, 3)):
            best = off + sub
            if (pid, eid) in ((3, 10), (0, 4)):
                break
    if best is None:
        return set()
    fmt = struct.unpack(">H", data[best:best + 2])[0]
    cps = set()
    if fmt == 4:
        segx2 = struct.unpack(">H", data[best + 6:best + 8])[0]
        seg = segx2 // 2
        ends = [struct.unpack(">H", data[best + 14 + i * 2:best + 16 + i * 2])[0] for i in range(seg)]
        sbase = best + 16 + segx2
        starts = [struct.unpack(">H", data[sbase + i * 2:sbase + 2 + i * 2])[0] for i in range(seg)]
        for s, e in zip(starts, ends):
            if s == 0xFFFF:
                continue
            cps.update(range(s, min(e, 0xFFFF) + 1))
    elif fmt == 12:
        ngroups = struct.unpack(">I", data[best + 12:best + 16])[0]
        for i in range(ngroups):
            g = best + 16 + i * 12
            sc, ec, _ = struct.unpack(">III", data[g:g + 12])
            if ec - sc > 0x20000:
                continue
            cps.update(range(sc, ec + 1))
    return cps


path = sys.argv[1]
data, tables = read_font(path)

print("file:", path.split("\\")[-1], "size:", len(data), "bytes")
for nid, text in font_names(data, tables)[:6]:
    label = {1: "family", 4: "full name", 6: "postscript"}.get(nid, str(nid))
    print(f"  {label}: {text}")

cps = cmap_codepoints(data, tables)
pua = {c for c in cps if 0xE000 <= c <= 0xF8FF or 0xF0000 <= c <= 0xFFFFD}
print("total codepoints:", len(cps))
print("Private Use Area codepoints:", len(pua))
powerline = {c for c in pua if 0xE0A0 <= c <= 0xE0D4}
print("powerline range (E0A0-E0D4):", len(powerline))

