(function(){
const out={};
for(const t of ['M365Princess','clean-detailed','cloud-native-azure','cobalt2']){
  const box=document.getElementById('svg-'+t);
  const svg=box&&box.querySelector('svg');
  if(!svg){out[t]='no svg';continue;}
  const rects=[...svg.querySelectorAll('rect')];
  const texts=[...svg.querySelectorAll('text')];
  const rec={svgH:svg.getAttribute('height'), rects:rects.length, texts:texts.length};
  // rect height vs text bbox height
  if(rects.length){rec.rectH=rects[0].getAttribute('height');}
  const th=texts.map(x=>{try{return Math.round(x.getBBox().height*10)/10}catch(e){return null}}).filter(Boolean);
  rec.textBBoxHeights=[...new Set(th)].slice(0,4);
  // textLength vs natural width
  const over=[];
  for(const x of texts.slice(0,40)){
    const tl=parseFloat(x.getAttribute('textLength')||'0');
    if(!tl) continue;
    const clone=x.cloneNode(true); clone.removeAttribute('textLength'); clone.removeAttribute('lengthAdjust');
    x.parentNode.appendChild(clone);
    let nat=0; try{nat=clone.getBBox().width}catch(e){}
    clone.remove();
    if(nat>tl*1.15) over.push({text:(x.textContent||'').slice(0,12), textLength:Math.round(tl), natural:Math.round(nat), ratio:+(nat/tl).toFixed(2)});
  }
  rec.runsWiderThanAllocated=over.slice(0,5);
  rec.overCount=over.length;
  out[t]=rec;
}
return JSON.stringify(out,null,1)})()

