// coordinate (see encodeRow's baseline), not a rect's top edge: the element
// deliberately carries no dominant-baseline attribute, so it renders on
// SVG's default alphabetic baseline (see Encode's doc comment). pin controls
// whether textLength/lengthAdjust is written at all — see writeRunText's doc
// comment on why a double-width glyph's own span must not be pinned.
func writeText(b *strings.Builder, text string, x, y, width float64, pin bool, rgb *color.RGB, attrs [8]uint8, blinkClass string) {
	b.WriteString(`<text x="`)
	b.WriteString(formatFloat(x))
	b.WriteString(`" y="`)
	b.WriteString(formatFloat(y))
	b.WriteString(`"`)

	if pin {
		b.WriteString(` textLength="`)
		b.WriteString(formatFloat(width))
		b.WriteString(`" lengthAdjust="spacingAndGlyphs"`)
	}

	if rgb != nil {
		b.WriteString(` fill="`)
		b.WriteString(hexString(*rgb))
		b.WriteString(`"`)

package terminal

import (
	"strings"

	"github.com/jandedobbeleer/oh-my-posh/src/color"
)

// CaptureRuns turns on the parallel Run stream Write/String build alongside the ANSI
// bytes they already emit, for a later encoder (an SVG renderer, eventually) to draw the
// prompt without parsing escape sequences. Off by default, mirroring Plain/Interactive:
// with it off, every capture site below is a single `if CaptureRuns` check and nothing
// else runs, so the ANSI hot path's allocation profile is unchanged (see the exact
// allocs/B-per-op gates in bench_test.go). With it on, capture is allowed to allocate.
var CaptureRuns bool

// RunMode discriminates the three ways writeSegmentColors (and writeAnchorOverride's
// matching branches) can render a segment or override. All three print bytes that read
// back as the same ANSI token "transparent" once decoded, so a Run needs this field to
// tell them apart; see writeSegmentColors' switch for the three branches it names.
type RunMode int

const (
	// RunNormal is a run rendered with its own foreground/background: neither of the
	// two transparent branches below applied.
	RunNormal RunMode = iota

	// RunBackgroundPainted is the branch taken when the foreground is transparent and a
	// terminal background color is known: the cell renders filled with the segment's own
	// background color, and the glyph itself renders in the terminal's default background
	// color, cutting its shape out of that fill — the SGR sequence sets the segment's
	// background as a foreground code, resets the background to default, then SGR 7
	// (reverse video) swaps the two, so what actually paints is the inverse of what the
	// codes name.
	RunBackgroundPainted

	// RunReverseVideo is the branch taken when the foreground is transparent and no
	// terminal background is known: reverse video (SGR 7) still swaps foreground/
	// background as described above, so the cell renders filled with the segment's own
	// background color; the glyph itself renders in whatever the real terminal's default
	// background turns out to be, which is unknown here (that's the "no terminal
	// background is known" half of this branch's condition).
	RunReverseVideo
)

// runAttributeSlots mirrors len(knownStyles): one nesting-depth counter per style
// anchor. knownStyles is a var, not a const, so this can't be derived at compile time;
// TestRunAttributeSlotsMatchesKnownStyles pins the two in sync.
const runAttributeSlots = 8

// Run is one contiguous span of text rendered under a single, unchanging style: the
// exact SGR pair and its pre-ToAnsi source form (a #RRGGBB hex, a colour name, accent,
// transparent, or a gradient definition — see color.History.Add), a render-mode
// discriminator, per-style-anchor nesting depth, and — for a cell stamped from the
// segment's own gradient — the true RGB behind the printed escape.
//
// Cells is the run's rendered width, a length delta matching what write() counts toward
// String()'s returned length; it can be zero (e.g. a hyperlink's URL text, which Text
// includes but write() never counts toward length) even when Text is non-empty.
type Run struct {
	BackgroundRGB    *color.RGB
	ForegroundRGB    *color.RGB
	Text             string
	Background       color.Ansi
	Foreground       color.Ansi
	BackgroundSource color.Ansi
	ForegroundSource color.Ansi
	Mode             RunMode
	Cells            int
	Attributes       [runAttributeSlots]uint8
}

// Runs returns the Run stream captured since the last String() call. Empty when
// CaptureRuns is false.
func Runs() []Run {
	return runsState.Runs
}

// runState bundles the run-capture bookkeeping threaded alongside colorState through the
// same style-anchor and color-change events (see colorState's own doc comment), only
// touched when CaptureRuns is true. text accumulates the pending run's content exactly as
// write() sends it to builder — see write()'s mirrored calls. depth is the running
// nesting counter per knownStyles slot, mutated at the three style-anchor emission sites
// (Write's leading-anchor prologue, writeAnchorOverride's Start/End cases) and reset
// alongside the writer's own end-of-segment SGR reset and in String()'s defer; attributes
// is depth's last snapshot, copied into a Run at flushRun. background/foreground/
// backgroundSource/foregroundSource/mode/backgroundRGB/foregroundRGB are the pending
// run's style, refreshed by syncPendingStyle after every event that can change it.
type runState struct {
	backgroundRGB    *color.RGB
	foregroundRGB    *color.RGB
	background       color.Ansi
	foreground       color.Ansi
	backgroundSource color.Ansi
	foregroundSource color.Ansi
	text             strings.Builder
	Runs             []Run
	mode             RunMode
	cellsAtFlush     int
	attributes       [runAttributeSlots]uint8
	depth            [runAttributeSlots]uint8
}

var runsState runState

// flushRun cuts the text accumulated since the last flush into a Run using the pending
// style snapshot (background/foreground/source/mode/attributes/RGB), then resets the
// text accumulator. A call with nothing accumulated — no text, no cell delta — is a
// no-op: several call sites flush unconditionally on entry (writeSegmentColors,
// writeAnchorOverride, endColorOverride all flush before touching any state), and most of
// those calls land here with nothing pending, since the previous flush already cut it.
func flushRun() {
	cells := length - runsState.cellsAtFlush
	text := runsState.text.String()

	if len(text) != 0 || cells != 0 {
		runsState.Runs = append(runsState.Runs, Run{
			Text:             text,
			Background:       runsState.background,
			Foreground:       runsState.foreground,
			BackgroundSource: runsState.backgroundSource,
			ForegroundSource: runsState.foregroundSource,
			BackgroundRGB:    runsState.backgroundRGB,
			ForegroundRGB:    runsState.foregroundRGB,
			Attributes:       runsState.attributes,
			Mode:             runsState.mode,
			Cells:            cells,
		})
	}

	runsState.text.Reset()
	runsState.cellsAtFlush = length
}

// syncPendingStyle snapshots cs's current active style — background/foreground/source,
// the render-mode discriminator, and the attribute nesting depth — as what governs
// whatever text comes next, and clears the gradient RGB (stampGradient sets it again,
// per cell, only for a channel it actually stamps). Called after every event that can
// change the active style: writeSegmentColors, writeAnchorOverride (including its
// style-anchor early returns, where only the attributes changed), and endColorOverride.
func syncPendingStyle(cs *colorState) {
	runsState.background = activeBackground(cs)
	runsState.foreground = activeForeground(cs)
	runsState.backgroundSource = activeBackgroundSource(cs)
	runsState.foregroundSource = activeForegroundSource(cs)
	runsState.mode = deriveRunMode(cs)
	runsState.attributes = runsState.depth
	runsState.backgroundRGB = nil
	runsState.foregroundRGB = nil
}

// activeBackgroundSource/activeForegroundSource are activeBackground/activeForeground's
// source-form counterparts: the top of the override history's source, or the segment
// base's source when no override is active.
func activeBackgroundSource(cs *colorState) color.Ansi {
	if bg := cs.currentColor.Background(); !bg.IsEmpty() {
		return cs.currentColor.BackgroundSource()
	}

	return cs.backgroundColorSource
}

func activeForegroundSource(cs *colorState) color.Ansi {
	if fg := cs.currentColor.Foreground(); !fg.IsEmpty() {
		return cs.currentColor.ForegroundSource()
	}

	return cs.foregroundColorSource
}

// deriveRunMode mirrors writeSegmentColors' own switch (and writeAnchorOverride's
// matching branches) on cs's now-current active foreground and the package-level
// terminal background, so a single derivation covers all three call sites instead of
// each branch setting it inline (which would have to be threaded through every early
// return).
func deriveRunMode(cs *colorState) RunMode {
	fg := activeForeground(cs)

	switch {
	case fg.IsTransparent() && len(BackgroundColor) != 0:
		return RunBackgroundPainted
	case fg.IsTransparent():
		return RunReverseVideo
	default:
		return RunNormal
	}
}

// Package svg renders a captured terminal.Run stream to a self-contained SVG
// document. It is a sibling encoder to the ANSI writer (see
// terminal.CaptureRuns): both start from the same Run stream, one emitting
// escape sequences, the other emitting markup, so neither has to parse the
// other's output.
package svg

import (
	"hash/fnv"
	"math"
	"strconv"
	"strings"

	"github.com/jandedobbeleer/oh-my-posh/src/color"
	"github.com/jandedobbeleer/oh-my-posh/src/terminal"
)

// Options configures the SVG canvas: font metrics, plus the two colors a Run
// stream cannot carry itself. BackgroundSource/ForegroundSource can hold
// "accent" or the ansiColorCodes name "default", both of which resolve
// against live package state in the ANSI writer (color.Defaults' accent,
// the real terminal background) rather than anything in the Run itself.
// Taking them as explicit fields — instead of Encode reaching for that
// package state — is what makes color resolution unit-testable.
type Options struct {
	TerminalBackground *color.RGB
	AccentForeground   *color.RGB
	AccentBackground   *color.RGB
	// CanvasBackground serves two roles that must stay the same color for a
	// reverse-video cutout to read as a hole punched through to the window
	// behind it, rather than a mismatched patch: it is both the glyph color
	// painted for a transparent-foreground run whose real terminal
	// background is unknown (terminal.RunReverseVideo — see paintRun) and,
	// since 6e2377a9, the fill of the terminal window Encode now draws
	// behind every row (see window.go). A real terminal shows its own
	// default background in both places; absent one to match, withDefaults
	// falls back to the retired PNG renderer's own fixed #151515 for both.
	CanvasBackground *color.RGB
	FontFamily       string
	FontSize         float64
	// CellWidth is the horizontal advance of one monospace cell, in the same
	// unit FontSize is (an absolute value, not a ratio of it — a caller sets
	// both explicitly, e.g. testOptions' FontSize:10/CellWidth:10 pairing).
	// Zero falls back to FontSize*defaultCellWidth (~0.6021em), Hack Nerd
	// Font's own advance ratio read straight from its hmtx table (ASCII 'M':
	// 1233 font units / 2048 units-per-em — see defaultCellWidth's doc
	// comment). That default matches the bundled font stack (see
	// defaultFontFamily), but the website renders these in Victor Mono,
	// whose advance ratio is measurably different (0.5455em) — a caller
	// with a different font should set CellWidth explicitly rather than
	// assume this default (see cli/config_export_svg.go's svgOptions for
	// how the CLI's --cell-width, quoted as a font-size ratio, converts to
	// this field's absolute unit).
	CellWidth float64
	// LineHeight is the vertical advance of one row, in the same absolute
	// unit as CellWidth. Zero falls back to FontSize*defaultLineHeight
	// (~1.397em), Hack Nerd Font's own hhea-derived line height times the
	// retired PNG renderer's lineSpacing constant (see defaultLineHeight's
	// doc comment). Like CellWidth, this is font-specific — Victor Mono's
	// is ~1.691em — and a caller rendering in a different font should set
	// it explicitly.
	LineHeight float64
	// Padding is the gap between the window's rounded edge and the content
	// grid on all four sides (the title bar reserves additional space of
	// its own above the top padding — see windowGeometry). It defaults to
	// FontSize, which is exactly the retired PNG renderer's own padding
	// constant (48px) scaled by FontSize/48 at this package's default
	// 16px FontSize — see newWindowGeometry's doc comment.
	Padding float64
	// Columns fixes the canvas' content width at Columns*CellWidth,
	// independent of any row's actual content: the terminal-window
	// presentation this package restores needs a stable frame size
	// regardless of what a theme renders, exactly like every reference PNG
	// the old renderer produced was a fixed-width window rather than one
	// that shrink-wrapped to content. Zero falls back to defaultColumns
	// (120), matching both the retired renderer's own default and the
	// image-export CLI command's --terminal-width flag default, so a
	// caller that doesn't set this still gets the terminal-shaped canvas
	// the reference PNGs always had.
	Columns int
}

const (
	defaultFontFamily = `"CaskaydiaCove Nerd Font", "FiraCode Nerd Font", "Hack Nerd Font", ui-monospace, monospace`
	defaultFontSize   = 16.0
	// defaultColumns matches the retired PNG renderer's own defaultColumns
	// and the image-export CLI command's --terminal-width flag default: a
	// caller that never sets Options.Columns still gets a 120-column window.
	defaultColumns = 120

	// defaultCellWidth is Hack Nerd Font's true advance ratio for an ASCII
	// glyph, read directly from the font's own hmtx table rather than
	// reverse-engineered from a rendered reference: HackNerdFont-Regular.ttf
	// reports unitsPerEm 2048 and an 'M' advance of 1233 units, 1233/2048 =
	// 0.60205...em. Every Nerd Font Private Use Area icon measured
	// alongside it (E0B0, F408, F044, E62A, E725, F489) also advances
	// exactly 1.000 cell, in both Hack and Victor Mono — the icons overflow
	// their own cell's ink, sometimes past 1.8 cells wide, but that is by
	// design (a terminal renders the next glyph a full cell over
	// regardless, letting the ink spill) and not something to budget extra
	// cell width for; see the now-removed doublewidth.go this package used
	// to carry for exactly that mistake.
	//
	// A prior version of this default used 7.0/12.0 (0.58333em), backed out
	// from the retired PNG renderer's own reference canvas arithmetic. That
	// number encodes a bug, not a font property: the PNG renderer computed
	// its advance via `font.Drawer.MeasureString(" ") >> 6`, a 26.6
	// fixed-point shift that truncates the fractional pixel rather than
	// rounding it (image.go's fontHeight/spaceAdvance). At its 48px
	// reference em, Hack's true advance is 48*0.60205 = 28.9px, which the
	// PNG renderer truncated down to 28px — 0.9px lost per column, 3.2% of
	// the true advance. Reproducing that truncation here would bake a
	// rounding defect specific to one em size into a vector format that has
	// no rounding to do at all, and it would be flatly wrong for any other
	// font or FontSize. See defaultLineHeight for the matching line-height
	// derivation and the residual drift this choice leaves against the old
	// PNG references.
	defaultCellWidth = 1233.0 / 2048.0

	// defaultLineHeight is Hack Nerd Font's own line height — hhea's
	// Ascender - Descender + LineGap, 2384 units at unitsPerEm 2048 =
	// 1.1641em — times 1.2, the retired PNG renderer's own lineSpacing
	// constant (image.go: `ir.lineSpacing = 1.2`, applied as
	// `regular.Metrics().Height * lineSpacing`, image.go ~:310-312,
	// ~:727-761). 1.1641 * 1.2 = 1.397em.
	//
	// A prior version of this default was a flat 1.4, backed out from the
	// PNG reference renders' pixel dimensions (48px em, 66px content rows,
	// 66/48 ≈ 1.375) rather than font metrics. That number is close to
	// Victor Mono's own ratio (1.4091 * 1.2 = 1.691em) but every reference
	// PNG was actually rendered in Hack (1.397em) — a coincidence of
	// fitting the wrong font, not a derivation. See defaultCellWidth's doc
	// comment for why a metric derived from the font, not from the old
	// renderer's rounded pixels, is the correct default here too.
	defaultLineHeight = (2384.0 / 2048.0) * 1.2
)

// defaultCanvasBackground is the retired PNG renderer's own fixed fallback
// (image.go's defaultBackgroundColor, #151515) for the glyph color a
// transparent-foreground run paints when no real terminal background is
// known; see Options.CanvasBackground.
var defaultCanvasBackground = color.RGB{R: 0x15, G: 0x15, B: 0x15}

// withDefaults fills every zero-value metric with a sensible default, so a
// caller only has to set the fields it cares about — typically just the two
// colors — and still gets a fully specified canvas.
func (o *Options) withDefaults() Options {
	out := *o

	if out.FontFamily == "" {
		out.FontFamily = defaultFontFamily
	}

	if out.FontSize == 0 {
		out.FontSize = defaultFontSize
	}

	if out.CellWidth == 0 {
		out.CellWidth = out.FontSize * defaultCellWidth
	}

	if out.LineHeight == 0 {
		out.LineHeight = out.FontSize * defaultLineHeight
	}

	if out.Padding == 0 {
		out.Padding = out.FontSize
	}

	if out.CanvasBackground == nil {
		out.CanvasBackground = &defaultCanvasBackground
	}

	if out.Columns <= 0 {
		out.Columns = defaultColumns
	}

	return out
}

// Encode renders rows of runs — one []terminal.Run per output row, as
// prompt.Engine.CapturedRuns returns — into a self-contained SVG document.
//
// Layout is a monospace cell grid: every run advances the running column by
// its own Cells, never by measuring glyphs. Each <text> element also carries
// textLength/lengthAdjust pinning it to exactly Cells*CellWidth, so it lands
// on the grid regardless of the browser's own font metrics. A Nerd Font
// icon's ink commonly overflows that one-cell box (see defaultCellWidth's
// doc comment on measured ink-vs-advance ratios) — that overflow is left
// alone, exactly like a real terminal lets a wide glyph draw over the
// following cell's left edge, rather than compensated for with extra grid
// width.
//
// A run with Cells == 0 (e.g. a hyperlink's URL text — see terminal.Run's
// doc comment) is skipped entirely: no rect, no text, no column advance.
//
// font-family/font-size/white-space are written as presentation attributes
// on the root <svg> element rather than a <style> rule: all three are
// ordinary inherited CSS properties, so every descendant <text> picks them
// up for free, and a document embedding many of these SVGs inline never gets
// a document-scoped <style> block fighting its own page styles. Each <text>
// element carries no dominant-baseline/alignment-baseline attribute at all,
// so it renders on SVG's default alphabetic baseline; encodeRow computes
// that baseline's y itself (rowTop + 0.75*LineHeight, see writeText) rather
// than anchoring to a rect edge via "hanging", because this package has no
// server-side font metrics and "hanging" baseline placement is implemented
// inconsistently across browsers — a computed alphabetic-baseline offset is
// deterministic everywhere instead.
//
// A <style> block is emitted only when a run actually blinks (attrBlink >
// 0): no bundled theme does, so a gallery of these SVGs carries no <style>
// at all. When one does blink, its class name and @keyframes name are
// suffixed with a hash of the row content, so two different blinking SVGs
// inlined on the same page never share (and can't clash on) the same
// document-scoped class/keyframes name.
//
// Encode takes opts by value, not by pointer, even though Options is 80
// bytes (over gocritic's hugeParam threshold): Encode runs once per prompt
// render, so the extra copy is immaterial next to the string-building it
// does, and the by-value signature keeps the public API's ergonomic call
// shape (Encode(rows, Options{...})) rather than forcing every caller through
// a throwaway local just to take its address.
//
//nolint:gocritic
func Encode(rows [][]terminal.Run, opts Options) (string, error) {
	opts = opts.withDefaults()
	rows = decorate(fitRows(rows, opts.Columns))

	blinks := false
	hasher := fnv.New64a()

	for _, row := range rows {
		for i := range row {
			if row[i].Attributes[attrBlink] > 0 {
				blinks = true
			}

			hasher.Write([]byte(row[i].Text))
			hasher.Write(row[i].Attributes[:])
		}
	}

	var blinkClass string
	if blinks {
		blinkClass = "omp-blink-" + strconv.FormatUint(hasher.Sum64(), 36)
	}

	geo := newWindowGeometry(&opts)
	size := newCanvasSize(&geo, opts.Columns, opts.CellWidth, len(rows), opts.LineHeight)

	var b strings.Builder

	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="`)
	b.WriteString(formatFloat(size.width))
	b.WriteString(`" height="`)
	b.WriteString(formatFloat(size.height))
	b.WriteString(`" viewBox="0 0 `)
	b.WriteString(formatFloat(size.width))
	b.WriteString(" ")
	b.WriteString(formatFloat(size.height))
	b.WriteString(`" font-family="`)
	b.WriteString(escapeAttr(opts.FontFamily))
	b.WriteString(`" font-size="`)
	b.WriteString(formatFloat(opts.FontSize))
	b.WriteString(`px" white-space="pre">`)
	b.WriteString("\n")

	if blinkClass != "" {
		writeBlinkStyle(&b, blinkClass)
	}

	// The window's own fill must stay the same color a reverse-video cutout
	// glyph paints (opts.CanvasBackground — see its doc comment), unless a
	// real terminal background is actually known, in which case that's the
	// more accurate choice for both.
	windowFill := *opts.CanvasBackground
	if opts.TerminalBackground != nil {
		windowFill = *opts.TerminalBackground
	}

	writeWindowChrome(&b, size, &geo, windowFill)

	for rowIndex, row := range rows {
		encodeRow(&b, row, rowIndex, size, opts, blinkClass)
	}

	b.WriteString("</svg>")

	return b.String(), nil
}

// fitRows applies fitRow (see fit.go) to every captured row when columns is
// positive, flattening any row that had to be collapsed/wrapped into
// several output rows. Options.withDefaults always leaves Columns positive
// (see its doc comment), so the columns <= 0 branch only matters for a
// caller that constructs opts by hand and skips withDefaults, e.g. a test.
func fitRows(rows [][]terminal.Run, columns int) [][]terminal.Run {
	if columns <= 0 {
		return rows
	}

	fitted := make([][]terminal.Run, 0, len(rows))

	for _, row := range rows {
		fitted = append(fitted, fitRow(row, columns)...)
	}

	return fitted
}

func writeBlinkStyle(b *strings.Builder, blinkClass string) {
	b.WriteString("<style>\n.")
	b.WriteString(blinkClass)
	b.WriteString(" { animation: ")
	b.WriteString(blinkClass)
	b.WriteString(" 1s steps(1, end) infinite; }\n@keyframes ")
	b.WriteString(blinkClass)
	b.WriteString(" { 50% { opacity: 0; } }\n</style>\n")
}

// paintState carries the last resolved, non-empty color per channel across
// runs in the same row. A Run whose source resolves to nothing — the ToAnsi
// failure path color.Defaults.ToAnsi documents (see resolveChannel) — must
// keep whatever was already active, exactly like a real terminal that never
// received an SGR code for that channel.
type paintState struct {
	fg *color.RGB
	bg *color.RGB
}

// encodeRow takes opts by value for the same reason Encode does (see its
// comment): it runs once per row, not once per Run, so the 80-byte copy
// gocritic flags is immaterial. size.contentX/contentY (see canvasSize) is
// the content grid's top-left corner inside the window, replacing what used
// to be a flat opts.Padding offset from the canvas edge before the window
// chrome existed.
//
//nolint:gocritic
func encodeRow(b *strings.Builder, runs []terminal.Run, rowIndex int, size canvasSize, opts Options, blinkClass string) {
	state := paintState{}
	cell := 0
	rowTop := size.contentY + float64(rowIndex)*opts.LineHeight

	// baseline places the glyphs roughly centered in the row instead of
	// hugging its top edge (see the "hanging" removal note on Encode): 0.75
	// of the row's height backed out from the retired PNG renderer's own
	// background-rect placement (bgY = y - fontLineHeight*0.75).
	baseline := rowTop + opts.LineHeight*0.75

	for i := range runs {
		run := &runs[i]
		textRGB, hasRect, rectRGB := paintRun(run, &state, &opts)

		if run.Cells == 0 {
			continue
		}

		x := size.contentX + float64(cell)*opts.CellWidth
		runWidth := float64(run.Cells) * opts.CellWidth

		if hasRect {
			writeRect(b, x, rowTop, runWidth, opts.LineHeight, *rectRGB)
		}

		if run.Text != "" {
			writeText(b, run.Text, x, baseline, runWidth, textRGB, run.Attributes, blinkClass)
		}

		cell += run.Cells
	}
}

func writeRect(b *strings.Builder, x, y, width, height float64, rgb color.RGB) {
	b.WriteString(`<rect x="`)
	b.WriteString(formatFloat(x))
	b.WriteString(`" y="`)
	b.WriteString(formatFloat(y))
	b.WriteString(`" width="`)
	b.WriteString(formatFloat(width))
	b.WriteString(`" height="`)
	b.WriteString(formatFloat(height))
	b.WriteString(`" fill="`)
	b.WriteString(hexString(rgb))
	b.WriteString("\"/>\n")
}

// writeText writes a <text> element whose y is already the baseline
// coordinate (see encodeRow's baseline), not a rect's top edge: the element
// deliberately carries no dominant-baseline attribute, so it renders on
// SVG's default alphabetic baseline (see Encode's doc comment).
func writeText(b *strings.Builder, text string, x, y, width float64, rgb *color.RGB, attrs [8]uint8, blinkClass string) {
	b.WriteString(`<text x="`)
	b.WriteString(formatFloat(x))
	b.WriteString(`" y="`)
	b.WriteString(formatFloat(y))
	b.WriteString(`" textLength="`)
	b.WriteString(formatFloat(width))
	b.WriteString(`" lengthAdjust="spacingAndGlyphs"`)

	if rgb != nil {
		b.WriteString(` fill="`)
		b.WriteString(hexString(*rgb))
		b.WriteString(`"`)
	}

	if attrs[attrBold] > 0 {
		b.WriteString(` font-weight="bold"`)
	}

	if attrs[attrItalic] > 0 {
		b.WriteString(` font-style="italic"`)
	}

	if decoration := textDecoration(attrs); decoration != "" {
		b.WriteString(` text-decoration="`)
		b.WriteString(decoration)
		b.WriteString(`"`)
	}

	if attrs[attrDim] > 0 {
		b.WriteString(` opacity="0.6"`)
	}

	if attrs[attrBlink] > 0 {
		b.WriteString(` class="`)
		b.WriteString(blinkClass)
		b.WriteString(`"`)
	}

	b.WriteString(">")
	b.WriteString(escapeXML(text))
	b.WriteString("</text>\n")
}

// attribute slot indices mirror knownStyles' order in terminal/writer.go
// (bold, underline, overline, italic, strikethrough, dim/faint, blink,
// reverse), which Run.Attributes' index space is keyed on; see run.go's
// runAttributeSlots.
const (
	attrBold = iota
	attrUnderline
	attrOverline
	attrItalic
	attrStrikethrough
	attrDim
	attrBlink
	attrReverse
)

func textDecoration(attrs [8]uint8) string {
	var parts []string

	if attrs[attrUnderline] > 0 {
		parts = append(parts, "underline")
	}

	if attrs[attrOverline] > 0 {
		parts = append(parts, "overline")
	}

	if attrs[attrStrikethrough] > 0 {
		parts = append(parts, "line-through")
	}

	return strings.Join(parts, " ")
}

// paintRun resolves the RGB a run's rect and text should paint, applying its
// RunMode (see terminal.RunMode's doc comment) and its reverse-video
// attribute. bold/italic/underline/overline/strikethrough/dim/blink are
// applied later, directly from Run.Attributes, since they don't affect which
// color goes where.
func paintRun(run *terminal.Run, state *paintState, opts *Options) (textRGB *color.RGB, hasRect bool, rectRGB *color.RGB) {
	fg, fgResolved := resolveChannel(run.ForegroundSource, run.ForegroundRGB, false, opts)
	if fgResolved {
		state.fg = fg
	}

	bg, bgResolved := resolveChannel(run.BackgroundSource, run.BackgroundRGB, true, opts)
	if bgResolved {
		state.bg = bg
	}

	switch run.Mode {
	case terminal.RunBackgroundPainted:
		// the foreground is transparent and a terminal background is known:
		// the cell fills with the segment's own background, and the glyph
		// is cut out of that fill in the terminal's own background color —
		// matching the real terminal rendering (see terminal.RunMode's doc
		// comment): SGR 7 swaps a foreground code carrying the segment's
		// background with the just-reset default background, so the segment
		// background ends up as the visible fill, not the glyph color.
		rectRGB = state.bg
		textRGB = opts.TerminalBackground
	case terminal.RunReverseVideo:
		// the foreground is transparent and no terminal background is
		// known: same cutout as above, but the glyph color is the real
		// terminal's default background, which this package can't observe —
		// opts.CanvasBackground stands in for it (see Options' doc comment).
		rectRGB = state.bg
		textRGB = opts.CanvasBackground
	default:
		textRGB = state.fg
		rectRGB = state.bg
	}

	// SGR 7 (reverse video) is a real terminal's on/off flag, not a counter:
	// sending it again while already in one of the writer's own
	// transparent-driven reverse renderings above changes nothing, so the
	// explicit <r> attribute only swaps anything in the RunNormal case.
	if run.Attributes[attrReverse] > 0 && run.Mode == terminal.RunNormal {
		textRGB, rectRGB = rectRGB, textRGB
	}

	hasRect = rectRGB != nil

	return textRGB, hasRect, rectRGB
}

// formatFloat renders v rounded to at most 2 decimal places, using the
// shortest representation that round-trips at that precision — an integer
// value still prints as "10", not "10.00" — since Encode's own arithmetic
// (cell/row counts times a float metric) routinely produces values like
// 140.79999999999998 that carry no visual meaning past the hundredths place.
func formatFloat(v float64) string {
	return strconv.FormatFloat(math.Round(v*100)/100, 'f', -1, 64)
}

func hexString(rgb color.RGB) string {
	const hexDigits = "0123456789abcdef"

	buf := [7]byte{'#'}

	for i, c := range [3]uint8{rgb.R, rgb.G, rgb.B} {
		buf[1+i*2] = hexDigits[c>>4]
		buf[2+i*2] = hexDigits[c&0x0f]
	}

	return string(buf[:])
}

func escapeXML(s string) string {
	return xmlReplacer.Replace(s)
}

var xmlReplacer = strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;")

// escapeAttr escapes a value destined for a double-quoted XML attribute.
// This is stricter than escapeXML: an attribute value like Options.FontFamily
// ordinarily contains literal double quotes (e.g. `"CaskaydiaCove Nerd
// Font", ui-monospace`), which was harmless as plain text content inside the
// old <style> block but would prematurely close a font-family="..." attribute
// if left unescaped.
func escapeAttr(s string) string {
	return attrReplacer.Replace(s)
}

var attrReplacer = strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&quot;")

package svg

import (
	"strings"

	"github.com/jandedobbeleer/oh-my-posh/src/color"
)

// windowGeometry is every coordinate the terminal-window chrome needs,
// derived once per Encode call from opts. All of it traces back to the
// retired PNG renderer's own constants (image.go's initDefaults/SavePNG, at
// its factor = 2.0): margin 96, padding 48, titleOffset 80, corner radius
// 12, traffic-light radius 18 spaced 50 apart, a 2px window border, and a
// stackblur shadow of radius 32 offset (32, 32). Those numbers are what the
// PNG renderer drew at its own reference em size — a 48px FontSize, backed
// out from the reference renders' fixed 3648×632 canvas (120 columns ×
// ~28px advance + 2×96 margin + 2×48 padding = 3648) — so every one of them
// is scaled here by FontSize/48 to keep the same proportions at this
// package's actual FontSize (16px by default) instead of reproducing the
// PNG renderer's pixel values verbatim.
type windowGeometry struct {
	margin       float64
	padding      float64
	titleOffset  float64
	corner       float64
	trafficR     float64
	trafficGap   float64
	trafficNudge float64
	strokeWidth  float64
	shadowBlur   float64
	shadowOffset float64
}

func newWindowGeometry(opts *Options) windowGeometry {
	scale := opts.FontSize / 48.0

	return windowGeometry{
		margin:       96 * scale,
		padding:      48 * scale,
		titleOffset:  80 * scale,
		corner:       12 * scale,
		trafficR:     18 * scale,
		trafficGap:   50 * scale,
		trafficNudge: 4 * scale,
		strokeWidth:  2 * scale,
		shadowBlur:   32 * scale,
		shadowOffset: 32 * scale,
	}
}

// canvasSize is every box the window chrome and content grid need, computed
// once from a row count and geometry: the window itself (the rounded rect
// with the traffic lights and content inside it), the canvas as a whole
// (the window plus the margin the drop shadow needs room to fall into), and
// the content grid's own top-left corner inside the window.
type canvasSize struct {
	width, height             float64 // the full <svg> canvas, margin included
	windowX, windowY          float64
	windowWidth, windowHeight float64
	contentX, contentY        float64
}

func newCanvasSize(geo *windowGeometry, columns int, cellWidth float64, rows int, lineHeight float64) canvasSize {
	contentWidth := float64(columns) * cellWidth
	contentHeight := float64(rows) * lineHeight

	windowWidth := contentWidth + 2*geo.padding
	windowHeight := contentHeight + 2*geo.padding + geo.titleOffset

	return canvasSize{
		width:  windowWidth + 2*geo.margin,
		height: windowHeight + 2*geo.margin,

		windowX:      geo.margin,
		windowY:      geo.margin,
		windowWidth:  windowWidth,
		windowHeight: windowHeight,

		contentX: geo.margin + geo.padding,
		contentY: geo.margin + geo.padding + geo.titleOffset,
	}
}

// trafficLightColors are the three window-control dots, left to right, in
// the retired PNG renderer's own fixed colors (image.go's red/yellow/green
// constants) — never resolved against a theme, since a real terminal
// emulator's own window chrome isn't themed by the shell prompt running
// inside it either.
var trafficLightColors = [3]string{"#ED655A", "#E1C04C", "#71BD47"}

// writeWindowChrome draws the terminal window itself: a drop shadow (an
// SVG-native <feDropShadow> filter standing in for the retired PNG
// renderer's own stackblur pass — see windowGeometry's doc comment) cast by
// a single rounded <rect>, since feDropShadow derives the shadow's shape
// from that rect's own alpha silhouette and composites the crisp rect back
// on top, so one element does the job the old renderer needed a separate
// blurred rect underneath for. Three traffic-light <circle>s complete the
// impression of a window with controls, exactly matching the reference PNG
// renders' layout.
//
// fill is the window's own background: opts.CanvasBackground, unless
// opts.TerminalBackground names a real, known terminal background, in
// which case that wins — see Options.CanvasBackground's doc comment on why
// a cutout glyph's color and the window's fill must always be the same
// value.
func writeWindowChrome(b *strings.Builder, size canvasSize, geo *windowGeometry, fill color.RGB) {
	const filterID = "omp-window-shadow"

	b.WriteString(`<defs><filter id="`)
	b.WriteString(filterID)
	b.WriteString(`" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="`)
	b.WriteString(formatFloat(geo.shadowOffset))
	b.WriteString(`" dy="`)
	b.WriteString(formatFloat(geo.shadowOffset))
	b.WriteString(`" stdDeviation="`)
	b.WriteString(formatFloat(geo.shadowBlur))
	// #10101066 (the retired renderer's shadowBaseColor) split into its own
	// flood-color/flood-opacity: 0x66/255 ≈ 0.4, feDropShadow's dedicated
	// alpha channel, rather than relying on 8-digit #RRGGBBAA hex support.
	b.WriteString(`" flood-color="#101010" flood-opacity="0.4"/></filter></defs>` + "\n")

	b.WriteString(`<rect class="omp-window" x="`)
	b.WriteString(formatFloat(size.windowX))
	b.WriteString(`" y="`)
	b.WriteString(formatFloat(size.windowY))
	b.WriteString(`" width="`)
	b.WriteString(formatFloat(size.windowWidth))
	b.WriteString(`" height="`)
	b.WriteString(formatFloat(size.windowHeight))
	b.WriteString(`" rx="`)
	b.WriteString(formatFloat(geo.corner))
	b.WriteString(`" fill="`)
	b.WriteString(hexString(fill))
	b.WriteString(`" stroke="#404040" stroke-width="`)
	b.WriteString(formatFloat(geo.strokeWidth))
	b.WriteString(`" filter="url(#`)
	b.WriteString(filterID)
	b.WriteString(`)"/>` + "\n")

	cy := size.windowY + geo.padding + geo.trafficNudge

	for i, hex := range trafficLightColors {
		cx := size.windowX + geo.padding + float64(i)*geo.trafficGap + geo.trafficNudge

		b.WriteString(`<circle class="omp-traffic-light" cx="`)
		b.WriteString(formatFloat(cx))
		b.WriteString(`" cy="`)
		b.WriteString(formatFloat(cy))
		b.WriteString(`" r="`)
		b.WriteString(formatFloat(geo.trafficR))
		b.WriteString(`" fill="`)
		b.WriteString(hex)
		b.WriteString(`"/>` + "\n")
	}
}

package svg

import (
	"github.com/jandedobbeleer/oh-my-posh/src/color"
	"github.com/jandedobbeleer/oh-my-posh/src/terminal"
)

// cursorText/watermarkText are the retired PNG renderer's own fixed cursor
// glyph and watermark string (image.go's cleanContent: ir.Cursor's default
// "_", and the literal "ohmyposh.dev" it always appended). The maintainer
// chose full parity with the old renderer here: both are kept, not just one
// of the two — see the task brief this package was rebuilt from.
const (
	cursorText    = "_"
	watermarkText = "ohmyposh.dev"
)

// decorate appends the retired PNG renderer's own trailing content — a
// cursor indicator glued onto the end of the last row of actual prompt
// content, then two blank lines, then the bold "ohmyposh.dev" watermark on
// its own line (image.go's cleanContent, ~:374-401: `ir.AnsiString +=
// "\n\n\x1b[1mohmyposh.dev\x1b[22m"`, two newlines before the watermark, not
// one) — to rows, returning a new slice rather than mutating the caller's
// own capture.
//
// Both additions use the ansiColorCodes name "default" as their foreground
// source rather than leaving it empty: an empty source means "keep
// whatever color was already active" (see resolveChannel's doc comment),
// which for the cursor would mean inheriting the last segment's own
// foreground — image.go's cursor and watermark render in the fixed default
// foreground color regardless of what precedes them, because cleanContent
// appends them after the prompt's own trailing SGR reset, and "default" is
// this package's equivalent of that reset state.
func decorate(rows [][]terminal.Run) [][]terminal.Run {
	if len(rows) == 0 {
		rows = [][]terminal.Run{{}}
	}

	rows = append([][]terminal.Run{}, rows...)
	last := len(rows) - 1

	cursorRow := make([]terminal.Run, len(rows[last]), len(rows[last])+1)
	copy(cursorRow, rows[last])
	cursorRow = append(cursorRow, terminal.Run{
		Text:             cursorText,
		Cells:            len(cursorText),
		ForegroundSource: color.Ansi("default"),
		// Explicit, not empty: an empty BackgroundSource means "keep
		// whatever was already active" (see resolveChannel's doc comment),
		// which here would paint the cursor with whatever segment's
		// background happened to end the row it's glued onto. The cursor
		// itself carries no background of its own, exactly like image.go's
		// reference renders show it.
		BackgroundSource: color.Transparent,
	})
	rows[last] = cursorRow

	rows = append(rows, nil, nil, []terminal.Run{{
		Text:             watermarkText,
		Cells:            len(watermarkText),
		ForegroundSource: color.Ansi("default"),
		Attributes:       [8]uint8{attrBold: 1},
	}})

	return rows
}

