1	#!/usr/bin/env node
2	// SVG-vs-PNG acceptance harness — a developer tool, not a CI gate.
3	//
4	// Builds the retired PNG renderer (from a worktree pinned to the last commit
5	// before PNG support was removed) and the current SVG-only renderer, exports
6	// the same themes from both against the same deterministic --data fixture,
7	// rasterizes each SVG headlessly in the *same font* the PNG renderer used
8	// (Hack Nerd Font) at a matched scale, diffs the raster against the
9	// reference PNG with pixelmatch, and writes an index.html contact sheet so a
10	// human can eyeball whether they still read as the same prompt.
11	//
12	// Usage (run from this directory, after `npm install` once):
13	//
14	//   node compare.mjs                          six default themes
15	//   node compare.mjs cobalt2 atomic            only the named themes
16	//   node compare.mjs --all                     every theme in ../../themes
17	//   node compare.mjs --skip-build               reuse bin/*.exe from a prior run
18	//   node compare.mjs --png-worktree <path>      override the old renderer's worktree
19	//
20	// Output lands in ./out/: <theme>.png (reference), <theme>.svg (exported),
21	// <theme>.raster.png (headless SVG raster), <theme>.diff.png, and
22	// index.html.
23	import { spawnSync } from "node:child_process";
24	import fs from "node:fs";
25	import path from "node:path";
26	import { fileURLToPath } from "node:url";
27	
28	import { PNG } from "pngjs";
29	import pixelmatch from "pixelmatch";
30	import { chromium } from "playwright";
31	
32	import { extractZipEntry } from "./zip.mjs";
33	
34	const __dirname = path.dirname(fileURLToPath(import.meta.url));
35	const REPO_ROOT = path.resolve(__dirname, "..", "..");
36	const THEMES_DIR = path.join(REPO_ROOT, "themes");
37	const DATA_FIXTURE = path.join(REPO_ROOT, "src", "prompt", "testdata", "fixtures", "prompt.data.json");
38	
39	const BIN_DIR = path.join(__dirname, "bin");
40	const FONT_DIR = path.join(__dirname, "fonts");
41	const OUT_DIR = path.join(__dirname, "out");
42	const FONT_PATH = path.join(FONT_DIR, "HackNerdFont-Regular.ttf");
43	const FONT_FAMILY = "Hack Nerd Font";
44	
45	const EXE = process.platform === "win32" ? ".exe" : "";
46	const OLD_BIN = path.join(BIN_DIR, `omp-png${EXE}`);
47	const NEW_BIN = path.join(BIN_DIR, `omp-svg${EXE}`);
48	
49	const DEFAULT_THEMES = [
50	  "M365Princess",
51	  "clean-detailed",
52	  "cloud-native-azure",
53	  "cobalt2",
54	  "jandedobbeleer",
55	  "atomic",
56	];
57	
58	// The PNG renderer's reference em size was 48px (see src/svg/window.go's
59	// newWindowGeometry doc comment); the SVG exporter has no --font-size flag
60	// and always renders at a 16px em (src/svg/svg.go's defaultFontSize). 48/16
61	// = 3, so rasterizing the SVG's own natural geometry at 3x device scale
62	// reproduces the PNG's reference resolution exactly, without needing a flag
63	// that doesn't exist. Every window-chrome constant in svg/window.go is
64	// already derived as `constant * (FontSize / 48)`, so this 3x upscale is
65	// mathematically the same shape the SVG package would produce if it *could*
66	// be asked for FontSize 48 directly.
67	const DEVICE_SCALE_FACTOR = 3;
68	
69	// pixelmatch match sensitivity. 0.1 is pixelmatch's own documented default
70	// and already tolerant of the antialiasing/subpixel noise a font rasterizer
71	// introduces; see parseArgs' --threshold for overriding it.
72	const DEFAULT_THRESHOLD = 0.1;
73	
74	function parseArgs(argv) {
75	  const opts = {
76	    themes: null,
77	    all: false,
78	    skipBuild: false,
79	    pngWorktree: process.env.OMP_PNG_WORKTREE || path.join(os_tmpdir(), "omp-png"),
80	    threshold: DEFAULT_THRESHOLD,
81	  };
82	
83	  const positional = [];
84	
85	  for (let i = 0; i < argv.length; i++) {
86	    const arg = argv[i];
87	
88	    switch (arg) {
89	      case "--all":
90	        opts.all = true;
91	        break;
92	      case "--skip-build":
93	        opts.skipBuild = true;
94	        break;
95	      case "--png-worktree":
96	        opts.pngWorktree = argv[++i];
97	        break;
98	      case "--threshold":
99	        opts.threshold = Number.parseFloat(argv[++i]);
100	        break;
101	      default:
102	        if (arg.startsWith("--")) {
103	          throw new Error(`unknown flag: ${arg}`);
104	        }
105	
106	        positional.push(arg);
107	    }
108	  }
109	
110	  if (positional.length > 0) {
111	    opts.themes = positional;
112	  }
113	
114	  return opts;
115	}
116	
117	function os_tmpdir() {
118	  return process.env.TEMP || process.env.TMP || "/tmp";
119	}
120	
121	function resolveThemeList(opts) {
122	  if (opts.all) {
123	    return fs
124	      .readdirSync(THEMES_DIR)
125	      .filter((f) => f.endsWith(".omp.json"))
126	      .map((f) => f.slice(0, -".omp.json".length))
127	      .sort();
128	  }
129	
130	  return opts.themes ?? DEFAULT_THEMES;
131	}
132	
133	function run(cmd, args, cwd) {
134	  console.log(`+ ${cmd} ${args.join(" ")}${cwd ? `  (in ${cwd})` : ""}`);
135	  const res = spawnSync(cmd, args, { cwd, stdio: "inherit", shell: false });
136	
137	  if (res.error) {
138	    throw res.error;
139	  }
140	
141	  if (res.status !== 0) {
142	    throw new Error(`command failed (exit ${res.status}): ${cmd} ${args.join(" ")}`);
143	  }
144	}
145	
146	function buildBinaries(opts) {
147	  fs.mkdirSync(BIN_DIR, { recursive: true });
148	
149	  const oldSrc = path.join(opts.pngWorktree, "src");
150	
151	  if (!fs.existsSync(oldSrc)) {
152	    throw new Error(
153	      `retired PNG renderer worktree not found at ${opts.pngWorktree} (expected a Go module at ${oldSrc}). ` +
154	        "Pass --png-worktree <path> to point at the worktree checked out at the last commit before PNG " +
155	        "support was removed.",
156	    );
157	  }
158	
159	  console.log("\nBuilding retired PNG renderer...");
160	  run("go", ["build", "-o", OLD_BIN, "."], oldSrc);
161	
162	  console.log("\nBuilding current SVG renderer...");
163	  run("go", ["build", "-o", NEW_BIN, "."], path.join(REPO_ROOT, "src"));
164	}
165	
166	// The PNG renderer downloads and caches Hack.zip itself (see
167	// cli/image/image.go's loadDefaultFonts); reuse that same cache instead of
168	// fetching it twice. Falls back to downloading it fresh if no cache is
169	// found anywhere.
170	function ensureFont() {
171	  if (fs.existsSync(FONT_PATH)) {
172	    return;
173	  }
174	
175	  fs.mkdirSync(FONT_DIR, { recursive: true });
176	
177	  const candidateCaches = [
178	    process.env.OMP_CACHE_DIR,
179	    process.platform === "win32" ? path.join(process.env.LOCALAPPDATA ?? "", "oh-my-posh") : null,
180	    process.env.XDG_CACHE_HOME ? path.join(process.env.XDG_CACHE_HOME, "oh-my-posh") : null,
181	    path.join(os_home(), ".cache", "oh-my-posh"),
182	  ].filter(Boolean);
183	
184	  for (const dir of candidateCaches) {
185	    const zipPath = path.join(dir, "Hack.zip");
186	
187	    if (fs.existsSync(zipPath)) {
188	      console.log(`Extracting HackNerdFont-Regular.ttf from cached ${zipPath}`);
189	      const zipBuf = fs.readFileSync(zipPath);
190	      const ttf = extractZipEntry(zipBuf, "HackNerdFont-Regular.ttf");
191	      fs.writeFileSync(FONT_PATH, ttf);
192	      return;
193	    }
194	  }
195	
196	  console.log("No cached Hack.zip found; downloading it (same URL the retired PNG renderer used)...");
197	  downloadAndExtractFont();
198	}
199	
200	function os_home() {
201	  return process.env.USERPROFILE || process.env.HOME || os_tmpdir();
202	}
203	
204	async function downloadAndExtractFont() {
205	  const url = "https://github.com/ryanoasis/nerd-fonts/releases/download/v3.2.1/Hack.zip";
206	  const res = await fetch(url);
207	
208	  if (!res.ok) {
209	    throw new Error(`failed to download ${url}: ${res.status} ${res.statusText}`);
210	  }
211	
212	  const zipBuf = Buffer.from(await res.arrayBuffer());
213	  const ttf = extractZipEntry(zipBuf, "HackNerdFont-Regular.ttf");
214	  fs.writeFileSync(FONT_PATH, ttf);
215	}
216	
217	function readPngDimensions(pngPath) {
218	  const buf = fs.readFileSync(pngPath);
219	  // IHDR is the first chunk in a well-formed PNG: 8-byte signature, 4-byte
220	  // length, 4-byte "IHDR", then width/height as big-endian uint32s.
221	  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
222	}
223	
224	// Renders svgMarkup inside a headless page whose viewport (at
225	// DEVICE_SCALE_FACTOR) targets targetWidth x targetHeight device pixels —
226	// the reference PNG's own dimensions — so the SVG's vector content is
227	// rescaled by the browser itself (crisp) rather than by resampling a raster
228	// afterwards. The SVG keeps its own viewBox, so content scales
229	// proportionally to fill the forced box.
230	async function rasterizeSVG(browser, svgMarkup, fontBase64, targetWidth, targetHeight) {
231	  const cssWidth = Math.max(1, Math.round(targetWidth / DEVICE_SCALE_FACTOR));
232	  const cssHeight = Math.max(1, Math.round(targetHeight / DEVICE_SCALE_FACTOR));
233	
234	  // The exporter's <svg> carries no preserveAspectRatio, so it defaults to
235	  // "xMidYMid meet": the browser would scale the viewBox uniformly to fit
236	  // inside the CSS box forced below and letterbox/center it, rather than
237	  // filling that box — which silently reintroduces a spatial offset between
238	  // the two rasters (content shifted down/right by the letterboxing gap)
239	  // that swamped the diff with edge noise before this fix. "none" makes the
240	  // two axes scale independently, actually filling cssWidth x cssHeight.
241	  svgMarkup = svgMarkup.replace("<svg ", '<svg preserveAspectRatio="none" ');
242	
243	  const context = await browser.newContext({
244	    viewport: { width: cssWidth, height: cssHeight },
245	    deviceScaleFactor: DEVICE_SCALE_FACTOR,
246	  });
247	
248	  const page = await context.newPage();
249	
250	  const html = `<!doctype html>
251	<html>
252	<head>
253	<meta charset="utf-8">
254	<style>
255	  @font-face {
256	    font-family: "${FONT_FAMILY}";
257	    src: url(data:font/ttf;base64,${fontBase64}) format("truetype");
258	    font-weight: normal;
259	    font-style: normal;
260	  }
261	  html, body { margin: 0; padding: 0; background: transparent; }
262	  /* Force the SVG's rendered box to exactly the viewport (which
263	     DEVICE_SCALE_FACTOR then rasterizes to targetWidth x targetHeight); the
264	     viewBox the exporter already wrote keeps the content proportional. */
265	  svg { display: block; width: 100vw; height: 100vh; }
266	</style>
267	</head>
268	<body>${svgMarkup}</body>
269	</html>`;
270	
271	  await page.setContent(html, { waitUntil: "networkidle" });
272	  await page.evaluate(() => document.fonts.ready);
273	  // One extra frame so the webfont swap (FOUT) has actually repainted
274	  // before the screenshot — document.fonts.ready resolves once the font is
275	  // *loaded*, not once the page has repainted with it.
276	  await page.waitForTimeout(50);
277	
278	  // omitBackground: true keeps the page's transparent regions transparent
279	  // in the captured PNG (alpha 0) instead of flattening them onto opaque
280	  // white. The reference PNG's own canvas outside the window+shadow is
281	  // genuinely transparent (image.go's gg context starts fully transparent
282	  // and is never filled) — matching that, rather than defaulting to white,
283	  // is what makes the outer margin diff meaningfully instead of reporting
284	  // "100% different" on every pixel of it.
285	  const buf = await page.screenshot({ omitBackground: true });
286	  await context.close();
287	
288	  return buf;
289	}
290	
291	// Pads the smaller of two RGBA buffers (top-left anchored) so both share the
292	// same width/height. The two rasters only ever differ by a few px of
293	// rounding slop (see rasterizeSVG's cssWidth/cssHeight rounding) once the
294	// SVG has already been forced to the PNG's own target dimensions, so a
295	// transparent-black pad — rather than scaling either image again, or
296	// cropping content away — is the least lossy way to reconcile that residual
297	// slop before a pixel-for-pixel diff.
298	function padToCommonSize(a, b) {
299	  const width = Math.max(a.width, b.width);
300	  const height = Math.max(a.height, b.height);
301	
302	  const pad = (img) => {
303	    if (img.width === width && img.height === height) {
304	      return img.data;
305	    }
306	
307	    const buf = Buffer.alloc(width * height * 4, 0);
308	
309	    for (let y = 0; y < img.height; y++) {
310	      img.data.copy(buf, y * width * 4, y * img.width * 4, (y * img.width + img.width) * 4);
311	    }
312	
313	    return buf;
314	  };
315	
316	  return { aData: pad(a), bData: pad(b), width, height };
317	}
318	
319	async function processTheme(theme, ctx) {
320	  const configPath = path.join(THEMES_DIR, `${theme}.omp.json`);
321	
322	  if (!fs.existsSync(configPath)) {
323	    throw new Error(`theme not found: ${configPath}`);
324	  }
325	
326	  const pngPath = path.join(OUT_DIR, `${theme}.png`);
327	  const svgPath = path.join(OUT_DIR, `${theme}.svg`);
328	  const rasterPath = path.join(OUT_DIR, `${theme}.raster.png`);
329	  const diffPath = path.join(OUT_DIR, `${theme}.diff.png`);
330	
331	  run(ctx.oldBin, [
332	    "config",
333	    "export",
334	    "image",
335	    "--config",
336	    configPath,
337	    "--data",
338	    DATA_FIXTURE,
339	    "--format",
340	    "png",
341	    "-o",
342	    pngPath,
343	  ]);
344	
345	  run(ctx.newBin, [
346	    "config",
347	    "export",
348	    "image",
349	    "--config",
350	    configPath,
351	    "--data",
352	    DATA_FIXTURE,
353	    "--font-family",
354	    FONT_FAMILY,
355	    "-o",
356	    svgPath,
357	  ]);
358	
359	  const { width: pngWidth, height: pngHeight } = readPngDimensions(pngPath);
360	  const svgMarkup = fs.readFileSync(svgPath, "utf8");
361	
362	  const rasterBuf = await rasterizeSVG(ctx.browser, svgMarkup, ctx.fontBase64, pngWidth, pngHeight);
363	  fs.writeFileSync(rasterPath, rasterBuf);
364	
365	  const png = PNG.sync.read(fs.readFileSync(pngPath));
366	  const raster = PNG.sync.read(rasterBuf);
367	
368	  const dimensionsMatched = png.width === raster.width && png.height === raster.height;
369	  const { aData, bData, width, height } = padToCommonSize(png, raster);
370	
371	  const diff = new PNG({ width, height });
372	  // includeAA: false marks antialiasing-only pixels (font hinting, shadow
373	  // falloff, the feDropShadow-vs-stackblur gap the task brief calls out as
374	  // expected and uninteresting) in the diff image without counting them —
375	  // this is the "structural" number, meant to track real content
376	  // differences (missing glyphs, wrong colors, misaligned icons) rather
377	  // than rasterizer noise. A second includeAA: true pass over the same
378	  // buffers (no image, just a count) reports how much of the raw pixel
379	  // difference that AA/blur noise actually was, for context.
380	  const structuralDiffPixels = pixelmatch(aData, bData, diff.data, width, height, {
381	    threshold: ctx.threshold,
382	    includeAA: false,
383	  });
384	  const rawDiffPixels = pixelmatch(aData, bData, null, width, height, {
385	    threshold: ctx.threshold,
386	    includeAA: true,
387	  });
388	
389	  fs.writeFileSync(diffPath, PNG.sync.write(diff));
390	
391	  const totalPixels = width * height;
392	
393	  return {
394	    theme,
395	    pngDims: `${png.width}x${png.height}`,
396	    rasterDims: `${raster.width}x${raster.height}`,
397	    dimensionsMatched,
398	    structuralPct: (structuralDiffPixels / totalPixels) * 100,
399	    rawPct: (rawDiffPixels / totalPixels) * 100,
400	    files: {
401	      png: `${theme}.png`,
402	      raster: `${theme}.raster.png`,
403	      diff: `${theme}.diff.png`,
404	    },
405	  };
406	}
407	
408	function writeIndexHtml(results) {
409	  const rows = results
410	    .map(
411	      (r) => `
412	    <section class="theme">
413	      <h2>${escapeHtml(r.theme)}</h2>
414	      <p class="stats">
415	        structural diff: <strong>${r.structuralPct.toFixed(2)}%</strong>
416	        &nbsp;·&nbsp; raw diff (incl. antialiasing): ${r.rawPct.toFixed(2)}%
417	        &nbsp;·&nbsp; PNG ${r.pngDims} vs raster ${r.rasterDims}${r.dimensionsMatched ? "" : " (padded to compare)"}
418	      </p>
419	      <div class="row">
420	        <figure>
421	          <figcaption>PNG (retired renderer)</figcaption>
422	          <div class="box"><img src="${r.files.png}" alt="${escapeHtml(r.theme)} PNG"></div>
423	        </figure>
424	        <figure>
425	          <figcaption>SVG raster (current renderer, Hack Nerd Font, ${DEVICE_SCALE_FACTOR}x)</figcaption>
426	          <div class="box"><img src="${r.files.raster}" alt="${escapeHtml(r.theme)} SVG raster"></div>
427	        </figure>
428	        <figure>
429	          <figcaption>diff (red = structural, yellow = antialiasing-only)</figcaption>
430	          <div class="box diffbox"><img src="${r.files.diff}" alt="${escapeHtml(r.theme)} diff"></div>
431	        </figure>
432	      </div>
433	    </section>`,
434	    )
435	    .join("\n");
436	
437	  const html = `<!doctype html>
438	<html>
439	<head>
440	<meta charset="utf-8">
441	<title>SVG vs PNG acceptance harness</title>
442	<style>
443	  :root { color-scheme: dark; }
444	  body {
445	    background: #14161a;
446	    color: #e6e9ef;
447	    font: 14px/1.5 system-ui, sans-serif;
448	    padding: 24px;
449	    margin: 0;
450	  }
451	  h1 { font-size: 18px; margin: 0 0 6px; }
452	  p.intro { color: #8b98a9; margin: 0 0 28px; max-width: 72ch; }
453	  h2 { font-size: 16px; margin: 0 0 4px; color: #9fd0ff; }
454	  .stats { font-size: 12px; color: #8b98a9; margin: 0 0 10px; }
455	  .row { display: flex; gap: 14px; flex-wrap: wrap; align-items: flex-start; }
456	  figure { margin: 0; }
457	  figcaption {
458	    font-size: 11px;
459	    text-transform: uppercase;
460	    letter-spacing: .06em;
461	    color: #8b98a9;
462	    margin: 0 0 4px;
463	  }
464	  .box {
465	    background: #0c0f14;
466	    border: 1px solid #232c39;
467	    border-radius: 6px;
468	    padding: 8px;
469	    overflow: auto;
470	    max-width: 640px;
471	    max-height: 260px;
472	  }
473	  .diffbox { background: #000; }
474	  img { display: block; width: auto; max-width: none; image-rendering: pixelated; }
475	  section.theme { margin-bottom: 40px; padding-bottom: 24px; border-bottom: 1px solid #232c39; }
476	</style>
477	</head>
478	<body>
479	  <h1>SVG exporter vs retired PNG renderer</h1>
480	  <p class="intro">
481	    Developer acceptance harness, not a CI gate. Each theme is exported from the retired PNG
482	    renderer and the current SVG renderer against the same deterministic --data fixture, both in
483	    Hack Nerd Font. The SVG is rasterized headlessly at ${DEVICE_SCALE_FACTOR}x scale (matching the
484	    PNG renderer's 48px reference em against the SVG's 16px default) before diffing with
485	    pixelmatch. Scroll each box independently; images are shown at native pixel size.
486	  </p>
487	  ${rows}
488	</body>
489	</html>`;
490	
491	  fs.writeFileSync(path.join(OUT_DIR, "index.html"), html);
492	}
493	
494	function escapeHtml(s) {
495	  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
496	}
497	
498	async function main() {
499	  const opts = parseArgs(process.argv.slice(2));
500	  const themes = resolveThemeList(opts);
501	
502	  if (!fs.existsSync(DATA_FIXTURE)) {
503	    throw new Error(`data fixture not found: ${DATA_FIXTURE}`);
504	  }
505	
506	  fs.mkdirSync(OUT_DIR, { recursive: true });
507	
508	  if (!opts.skipBuild) {
509	    buildBinaries(opts);
510	  } else if (!fs.existsSync(OLD_BIN) || !fs.existsSync(NEW_BIN)) {
511	    throw new Error("--skip-build was passed but bin/omp-png.exe / bin/omp-svg.exe are missing; run once without it first");
512	  }
513	
514	  ensureFont();
515	  const fontBase64 = fs.readFileSync(FONT_PATH).toString("base64");
516	
517	  console.log(`\nComparing ${themes.length} theme(s): ${themes.join(", ")}\n`);
518	
519	  const browser = await chromium.launch();
520	  const ctx = { oldBin: OLD_BIN, newBin: NEW_BIN, browser, fontBase64, threshold: opts.threshold };
521	
522	  const results = [];
523	
524	  try {
525	    for (const theme of themes) {
526	      console.log(`\n=== ${theme} ===`);
527	      const result = await processTheme(theme, ctx);
528	      results.push(result);
529	      console.log(
530	        `  structural diff: ${result.structuralPct.toFixed(2)}%  raw diff: ${result.rawPct.toFixed(2)}%  ` +
531	          `(PNG ${result.pngDims} vs raster ${result.rasterDims})`,
532	      );
533	    }
534	  } finally {
535	    await browser.close();
536	  }
537	
538	  writeIndexHtml(results);
539	
540	  console.log("\n--- Summary ---");
541	  for (const r of results) {
542	    console.log(`${r.theme.padEnd(24)} structural ${r.structuralPct.toFixed(2).padStart(6)}%   raw ${r.rawPct.toFixed(2).padStart(6)}%`);
543	  }
544	
545	  console.log(`\nContact sheet: ${path.join(OUT_DIR, "index.html")}`);
546	}
547	
548	main().catch((err) => {
549	  console.error(err);
550	  process.exitCode = 1;
551	});
552

