1	package svg
2	
3	import (
4		"strconv"
5		"strings"
6	
7		"github.com/jandedobbeleer/oh-my-posh/src/color"
8	)
9	
10	// resolveChannel resolves one channel (background or foreground) of a Run to
11	// an RGB value, given the run's own captured RGB (set only for a gradient
12	// cell — see terminal.Run's doc comment, populated from color.GradientCellsRGB
13	// rather than inverted from an SGR escape) and the run's pre-ToAnsi source
14	// form (a #RRGGBB hex, an ansiColorCodes name, "accent", a 0-255 palette
15	// index, "transparent", or empty).
16	//
17	// The bool return reports whether the source actually resolved to something.
18	// False means color.Defaults.ToAnsi's failure path: nothing was emitted (an
19	// unresolved palette key, a malformed hex, ...), so the caller must keep
20	// whatever color was already active on that channel, exactly like a real
21	// terminal that never received an SGR code for it. True with a nil RGB means
22	// the source resolved to "paint nothing here" (transparent, or an unset
23	// accent/terminal background) — also a real resolution, just not a color,
24	// and it must override whatever was active before it.
25	func resolveChannel(source color.Ansi, rgb *color.RGB, isBackground bool, opts *Options) (*color.RGB, bool) {
26		if rgb != nil {
27			return rgb, true
28		}
29	
30		if source.IsEmpty() {
31			return nil, false
32		}
33	
34		if source.IsTransparent() {
35			return nil, true
36		}
37	
38		if source == color.Accent {
39			return resolveAccent(isBackground, opts)
40		}
41	
42		value := source.String()
43	
44		if strings.HasPrefix(value, "#") {
45			return hexToRGB(value)
46		}
47	
48		if rgb, ok := namedRGB(value, isBackground, opts); ok {
49			return rgb, true
50		}
51	
52		if index, err := strconv.ParseUint(value, 10, 8); err == nil {
53			rgb := palette256(uint8(index))
54			return &rgb, true
55		}
56	
57		return nil, false
58	}
59	
60	// resolveAccent resolves the "accent" keyword against Options' pre-resolved
61	// accent RGB. An unset accent (opts.Accent* nil) mirrors color.Defaults.ToAnsi
