// hexToRGB mirrors the accepted forms of gookit's color.HexToRgb — the
// parser color.Defaults.ToAnsi ultimately hands a `#`-prefixed color to (see
// color/colors.go's `color.HEX(colorString, isBackground)` call) — rather
// than accepting only the canonical #RRGGBB. Anything ToAnsi resolves has
// already been written into the ANSI stream as a real SGR code, so a form
// this parser rejects is not "no color" but a color the terminal painted and
// the SVG silently dropped: resolveChannel reads a false here as "keep
// whatever was active", which after a leading diamond is the segment's own
// background — text painted in its own background color, invisible. Six
// bundled themes write 3-digit shorthand (#fff/#FFF/#000) and rendered
// exactly that way before this: cert, iterm2, montys, poshmon, uew, unicorn.
//
// gookit's rules, in its own order: strip a leading `#`, lowercase, expand a
// 3-digit shorthand by doubling each digit, strip a `0x` prefix from an
// 8-character value, then require exactly 6 hex digits.
func hexToRGB(value string) (*color.RGB, bool) {
	hex := strings.ToLower(strings.TrimPrefix(value, "#"))

	switch len(hex) {
	case 3:
		hex = string([]byte{hex[0], hex[0], hex[1], hex[1], hex[2], hex[2]})
	case 8:
		hex = strings.TrimPrefix(hex, "0x")
	}

	if len(hex) != 6 {
		return nil, false
	}

